INSERT OR REPLACE INTO LocalizedText(Tag, Text, Language) VALUES
('LOC_SLTH_UNIT_BEASTMASTER_DESCRIPTION', 'The top fighter of the Recon line. Converts defeated animals and the rare beast class unit. 50% increased [ICON_Production]Production with a Grove.', 'en_US'),
('LOC_SLTH_UNIT_MYCONID_DESCRIPTION', 'Khazad Beastmaster replacement. Can immobilize adjacent enemies with the Spores spell. Lacks the Beastmaster bonuses against Beasts and Animals. 50% increased [ICON_Production]Production with a Grove.', 'en_US'),
('LOC_SLTH_UNIT_CANNON_DESCRIPTION', 'Cannons are more powerful siege engines than catapults, but fill the same roles: lowering city defense bonuses and causing collateral damage. They require the gunpowder resource. 50% increased [ICON_Production]Production with a Siege Workshop.', 'en_US'),
('LOC_SLTH_UNIT_DWARVEN_CANNON_DESCRIPTION', 'Khazad Cannon replacement. Stronger, and collateral damage to adjacent targets up to 99%.* 50% increased [ICON_Production]Production with a Siege Workshop.', 'en_US'),
('LOC_SLTH_UNIT_CHARIOT_DESCRIPTION', 'Chariots require [ICON_RESOURCE_HORSES]horses, but provide a unit a decent way to soften up advanced enemy units with their strong attack and withdrawal. They lack much defensive strength, though, so they need a protected place to retreat to if they are to survive retaliation. 50% increased [ICON_Production]Production with a Siege Workshop.', 'en_US'),
('LOC_SLTH_UNIT_SWORDSMAN_DESCRIPTION', 'Strong Classical era melee unit. 50% increased [ICON_Production]Production with a Training Yard.', 'en_US'),
('LOC_SLTH_UNIT_MOROI_DESCRIPTION', 'Calabim Swordsman replacement. Can cast Burning Blood, giving additional movement and strength, but with a risk of becoming a barbarian unit each turn until it wears off.  50% increased [ICON_Production]Production with a Training Yard.', 'en_US'),
('LOC_SLTH_UNIT_CHAMPION_DESCRIPTION', 'Champions are the upgrades of Axemen and Swordsmen. Their main role remains the same, primarily conquest of enemy cities. They can upgrade into any of three or four quite different units, so consider your goal when choosing promotions for them.  50% increased [ICON_Production]Production with a Training Yard.', 'en_US'),
('LOC_SLTH_UNIT_OGRE_DESCRIPTION', 'Clan Champion replacement. Stronger but more expensive. Requires Iron. 50% increased [ICON_Production]Production with a Training Yard.', 'en_US'),
('LOC_SLTH_UNIT_DRAGON_SLAYER_DESCRIPTION', 'Grigori Champion Replacement. Starts with the Courage buff, and the Dragon Slaying Ability.  50% increased [ICON_Production]Production with a Training Yard.', 'en_US'),
('LOC_SLTH_UNIT_LONGBOWMAN_DESCRIPTION', 'The best non-limited city defender is the Longbowman. Start with a high bonus to city defense. 50% increased [ICON_Production]Production with a Archery Range.', 'en_US'),
('LOC_SLTH_UNIT_FIREBOW_DESCRIPTION', 'Amurite Longbowman Replacement. Starts with Channelling II. 50% increased [ICON_Production]Production with a Archery Range.', 'en_US'),
('LOC_SLTH_UNIT_HORSEMAN_DESCRIPTION', 'Useful for pillaging or rapid response to enemy incursion, or you can use their withdrawal chance to weaken an entrenched defender. 50% increased [ICON_Production]Production with a Stable.', 'en_US'),
('LOC_SLTH_UNIT_HORSE_ARCHER_DESCRIPTION', 'The Horse Archer does everything the Horseman does, but better. More strength and the addition of a first strike and first strike immune abilities make them flexible troops. 50% increased [ICON_Production]Production with a Stable.', 'en_US'),
('LOC_SLTH_UNIT_KNIGHT_DESCRIPTION', 'High strength, high movement rate, and a decent withdrawal rate combine to form a strong utility unit. There is no best use for a Knight, its the fact that they can do many things so well that make them so valuable. 50% increased [ICON_Production]Production with a Stable.', 'en_US'),
('LOC_SLTH_UNIT_HORNGUARD_DESCRIPTION', 'Khazad Khight replacement. No Resource requirement.  50% increased [ICON_Production]Production with a Stable.', 'en_US'),
('LOC_SLTH_UNIT_DEATH_KNIGHT_DESCRIPTION', 'The Death Knight combines the strength and mobility of a typical knight with the ability to cast Death Spells. 50% increased [ICON_Production]Production with a Stable.', 'en_US'),
('LOC_SLTH_UNIT_WAR_TORTOISE_DESCRIPTION', 'Lanun Knight replacement. Reduced Movement, but has the Amphibious promotion. 50% increased [ICON_Production]Production with a Siege Workshop.', 'en_US'),
('LOC_SLTH_UNIT_BISON_RIDER_DESCRIPTION', 'Doviello Knight replacement. One less Movement, but higher Combat Strength.  50% increased [ICON_Production]Production with a Stable.', 'en_US'),
('LOC_SLTH_UNIT_HARLEQUIN_DESCRIPTION', 'Balseraph Ranger replacement. Starts with the Taunt spell, which can cause nearby enemy units to attack an adjacent enemy. Can use Chaos Magic up to rank II.*  50% increased [ICON_Production]Production with a Carnival.', 'en_US'),
('LOC_SLTH_UNIT_VAMPIRE_DESCRIPTION', 'Calabim Champion replacement, unlocked at Feudalism. Starts with Vampirism, allowing them to feed on your cities, reducing the population, but gaining experience. They can also learn shadow and death spells up to rank 2*. 50% increased [ICON_Production]Production with a Governor''s Manor.', 'en_US'),
('LOC_SLTH_UNIT_STYGIAN_GUARD_DESCRIPTION', 'Stygian Guards are Immune to Disease, like all Demons, and heal faster than men, as indicated by their March promotion. 50% increased [ICON_Production]Production with a Temple of the Overlords.', 'en_US'),
('LOC_SLTH_UNIT_PARAMANDER_DESCRIPTION', 'Paramanders are specific to those that have the Runes of Kilmorph state religion. They are upgrades to soldiers of Kilmorph and start with medic and demon slaying. 50% increased [ICON_Production]Production with a Temple of Kilmorph.', 'en_US'),
('LOC_SLTH_UNIT_HUNTER_DESCRIPTION', 'Hunters continue the Scout tradition of 2 movement and bonus strength against animals. They can also carry Hawks and use them to scout out areas without having to waste time or risk their lives investigating it themselves. 50% increased [ICON_Production]Production with a Hunting Lodge.', 'en_US'),
('LOC_SLTH_UNIT_RANGER_DESCRIPTION', 'Rangers can carry hawks, and carry on a Scouts increased movement rate. Use them to scout the map, especially to clear off barbarian units that are to strong for your hunters. Although Rangers are powerful units but they get a penalty when attacking cities. So use them to clear the unsettled lands around your enemies cities and leave city attacks to your melee units. 50% increased [ICON_Production]Production with a Hunting Lodge.', 'en_US'),
('LOC_SLTH_UNIT_HELLHOUND_DESCRIPTION', 'Hell Hounds are faster than the Hunters they replace, allowing them to slip quickly into enemy lands for exploration or to harass enemies. 50% increased [ICON_Production]Production with a Hunting Lodge.', 'en_US'),
('LOC_SLTH_UNIT_DIVIDED_SOUL_DESCRIPTION', 'Sidar Hunter replacement. Can summon a permanent Severed Soul unit that can traverse all terrain. This can be activated at any time to consume it, moving the Divided Soul to its location. 50% increased [ICON_Production]Production with a Hunting Lodge.', 'en_US');
